// HasTablemeta applies the HasEdge predicate on the "tablemeta" edge.
func HasTablemeta() predicate.TableColumn {
	return predicate.TableColumn(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TablemetaTable, TablemetaColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTablemetaWith applies the HasEdge predicate on the "tablemeta" edge with a given conditions (other predicates).
func HasTablemetaWith(preds ...predicate.TableMeta) predicate.TableColumn {
	return predicate.TableColumn(func(s *sql.Selector) {
		step := newTablemetaStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TableColumn) predicate.TableColumn {
	return predicate.TableColumn(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TableColumn) predicate.TableColumn {
	return predicate.TableColumn(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TableColumn) predicate.TableColumn {
	return predicate.TableColumn(sql.NotPredicates(p))
}
